CREATE TABLE rule_spacecraft_journey_execution(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id),jump_duration_base_hours smallint NOT NULL CHECK(jump_duration_base_hours>0),jump_duration_dice_count smallint NOT NULL CHECK(jump_duration_dice_count>0),jump_duration_die_sides smallint NOT NULL CHECK(jump_duration_die_sides>1),successful_jump_route_required boolean NOT NULL,consume_planned_resources_on_departure boolean NOT NULL,move_ship_on_arrival boolean NOT NULL,advance_campaign_clock boolean NOT NULL);
COMMENT ON TABLE rule_spacecraft_journey_execution IS 'CE-TRAVEL-001 source-bound journey-leg departure and arrival execution.';
